#!/usr/bin/env python3
"""Generate Nemu64's initialized CIC transition and history arrays as C source.

This regenerates the data at 0x440B10..0x460D10, independently of the original
executable. It is an inferred reconstruction of table-generation logic, not a
claim that Nemu64's original generator used this source. The CIC algorithm is
adapted from X-Scale's 2011 implementation; see CIC6105-LICENSE.txt and the
provenance in generate_pif_table.py.
"""

import argparse
import hashlib
import json
from pathlib import Path
import sys

# This build helper must not leave generated bytecode in the source directory.
sys.dont_write_bytecode = True
from generate_pif_table import KEY_TABLES, next_state


ARRAYS = (
    ('PifResponseTable1', 0x440b10, 256,
     '2f44bbdec70ab52cb3a895b8dc59951cdae2f468f7adfaec76f819e243c76a0c'),
    ('PifResponseTable0', 0x440c10, 256,
     'ad6de70d22f5940cd0226174abfb440e1322553fbb721b2bafab83e30cdd17f6'),
    ('PifResponseHistory', 0x440d10, 131072,
     'df703cad54ed74356b3036b92ce3862189cf4848668745fc5045d992cc2f4813'),
)
AMBIGUOUS_RESPONSES = (1, 9, 11, 14)


def generate():
    # Each row maps (previous response, next challenge) to the next response.
    table1, table0 = (
        bytes((keys[previous] + 5 * challenge) & 15
              for previous in range(16) for challenge in range(16))
        for keys in reversed(KEY_TABLES)
    )

    history = bytearray()
    for challenge_prefix in range(1 << 16):
        key, table, response_prefix = 11, 0, 0
        for shift in (12, 8, 4, 0):
            challenge = (challenge_prefix >> shift) & 15
            response = (key + 5 * challenge) & 15
            response_prefix = (response_prefix << 4) | response
            key, table = next_state(table, response)
        if table == 0:
            continue

        # The original entries retain the first ambiguous fifth response. The
        # consumer masks this final nibble off when comparing four responses.
        for fifth_challenge in range(16):
            fifth_response = (key + 5 * fifth_challenge) & 15
            if fifth_response in AMBIGUOUS_RESPONSES:
                break
        word = (response_prefix << 4) | fifth_response
        history.extend(word.to_bytes(4, 'big'))

    return table1, table0, bytes(history)


def emit_c(tables):
    lines = [
        '// Generated by res/generate_pif_tables.py. Do not edit.',
        '// Semantic names are inferred; array contents and ordering are exact.',
        '// See res/README.md and res/CIC6105-LICENSE.txt for provenance.',
        '',
    ]
    for (name, address, size, _), data in zip(ARRAYS, tables):
        if size == 256:
            lines += [f'// Original VA 0x{address:08X}; indexed by response * 16 + challenge.',
                      f'unsigned char {name}[256] = {{']
            for offset in range(0, size, 16):
                values = ', '.join(f'0x{x:02X}' for x in data[offset:offset + 16])
                lines.append('    ' + values + ',')
        else:
            lines += [f'// Original VA 0x{address:08X}; five packed response nibbles.',
                      '// Numeric DWORDs preserve the original big-endian byte layout.',
                      f'unsigned long {name}[32768] = {{']
            words = [int.from_bytes(data[offset:offset + 4], 'little')
                     for offset in range(0, size, 4)]
            for offset in range(0, len(words), 8):
                values = ', '.join(f'0x{x:08X}UL' for x in words[offset:offset + 8])
                lines.append('    ' + values + ',')
        lines += ['};', '']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('output', type=Path, help='generated PifTables.inc path')
    parser.add_argument('--report', type=Path)
    args = parser.parse_args()
    tables = generate()
    records = []
    for (name, address, size, expected), data in zip(ARRAYS, tables):
        digest = hashlib.sha256(data).hexdigest()
        if len(data) != size or digest != expected:
            raise RuntimeError(f'{name} does not match the original initialized data')
        records.append(dict(name=name, original_va=f'0x{address:08X}',
                            size=size, sha256=digest, expected_sha256=expected,
                            exact=True))
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(emit_c(tables))
    if args.report:
        report = dict(generator='src/nemu64/res/generate_pif_tables.py',
                      generated_source=str(args.output), arrays=records,
                      total_size=sum(map(len, tables)),
                      combined_sha256=hashlib.sha256(b''.join(tables)).hexdigest())
        args.report.parent.mkdir(parents=True, exist_ok=True)
        args.report.write_text(json.dumps(report, indent=2) + '\n')
    print(f'{args.output}: 3 exact initialized arrays, 131584 data bytes')


if __name__ == '__main__':
    main()
